style.css:
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 55px;
  background: url(https://i.postimg.cc/x1hp41cV/D17.png) repeat;
  pointer-events: none;
  z-index: 9999;
}

body::after {
  content: "";
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 55px;
  background: url(https://i.postimg.cc/x1hp41cV/D17.png) repeat;
  transform: rotateZ(180deg);
  pointer-events: none;
  z-index: 9999;
}
